package protocol
import ("bytes"; "encoding/json"; "io")
// Decode 仅对调用方提供的内存或流输入执行解析。
func Decode(r io.Reader) (any,error) {
 raw,err:=io.ReadAll(r);if err!=nil{return nil,err};var v any
 err=json.Unmarshal(bytes.TrimSpace(raw),&v);return v,err
}

